var csvRows=await Parse(Encoding.UTF8.GetBytes(csv),"synthetic.csv");
Check(csvRows[1].PurchaseDate==new DateTime(2026,8,25)&&csvRows[1].InvoiceNo=="SYNTH-002","CSV metadata uses same fill-down as Excel");
