 var normalProtected=await http.PostAsJsonAsync("/checks/normal-import",new{rows=new[]{new{name="Demo Widget",barcode="SYNTH-BC",resolution="UPDATE",unit="PCS",mrp=999,purchasePrice=999,salePrice=999,gstMode="INCLUSIVE"}}});Check(normalProtected.IsSuccessStatusCode,"Protected normal match returns a report");
