 Check(Convert.ToInt32(await new SqlCommand("SELECT COUNT(*) FROM Products WHERE Id="+protectedId+" AND Mrp=150 AND SalePrice=135 AND Dis_Rate=10",connection).ExecuteScalarAsync())==1,"Protected normal import does not overwrite the purchase-updated master");
  var inventoryId=Convert.ToInt32(await new SqlCommand("INSERT Products(Name,Unit,PurchasePrice,SalePrice,Mrp,IsActive) OUTPUT INSERTED.Id VALUES('Inventory Widget','PCS',10,15,20,1)",connection).ExecuteScalarAsync());
  var inventoryBatch=Convert.ToInt32(await new SqlCommand("INSERT ProductBatches(ProductId,BatchNo,Quantity,CostPrice,SellingPrice,Mrp,ExpiryDate) OUTPUT INSERTED.Id VALUES("+inventoryId+",'INV-BASE',10,10,15,20,'2030-12-31')",connection).ExecuteScalarAsync());
  await new SqlCommand("INSERT StockLedger(ProductId,BatchId,MovementType,Quantity,ReferenceType,Notes) VALUES("+inventoryId+","+inventoryBatch+",'OPENING',10,'OPENING','inventory check')",connection).ExecuteNonQueryAsync();
  var damage=await http.PostAsJsonAsync("/api/inventory/damage",new{productId=inventoryId,quantity=2,reason="Damaged",notes="SQL check"});Check(damage.IsSuccessStatusCode,"Inventory damage posts transactionally: "+await damage.Content.ReadAsStringAsync());
  Check(Convert.ToDecimal(await new SqlCommand("SELECT Quantity FROM ProductBatches WHERE Id="+inventoryBatch,connection).ExecuteScalarAsync())==8,"Damage deducts source batch");
  Check(Convert.ToInt32(await new SqlCommand("SELECT COUNT(*) FROM StockLedger WHERE ProductId="+inventoryId+" AND MovementType='DAMAGE' AND Quantity=-2",connection).ExecuteScalarAsync())==1,"Damage ledger movement exists");
  var receive=await http.PostAsJsonAsync("/api/inventory/receive",new{productId=inventoryId,quantity=3,batchNo="INV-REC",expiryDate="2031-12-31",costPrice=11,salePrice=16,mrp=21,sourceName="Branch B",referenceNo="REF-001",notes="SQL check"});Check(receive.IsSuccessStatusCode,"Inventory receive posts transactionally: "+await receive.Content.ReadAsStringAsync());
  Check(Convert.ToDecimal(await new SqlCommand("SELECT SUM(Quantity) FROM ProductBatches WHERE ProductId="+inventoryId,connection).ExecuteScalarAsync())==11,"Receive increases stock");
  var transfer=await http.PostAsJsonAsync("/api/inventory/transfer",new{toOutlet="Branch B",notes="SQL check",lines=new[]{new{productId=inventoryId,quantity=4}}});Check(transfer.IsSuccessStatusCode,"Inventory transfer posts transactionally: "+await transfer.Content.ReadAsStringAsync());
  Check(Convert.ToDecimal(await new SqlCommand("SELECT SUM(Quantity) FROM ProductBatches WHERE ProductId="+inventoryId,connection).ExecuteScalarAsync())==7,"Transfer deducts source stock");
  Check(Convert.ToInt32(await new SqlCommand("SELECT COUNT(*) FROM StockTransfers t JOIN StockTransferLines l ON l.TransferId=t.Id WHERE t.ToOutlet='Branch B' AND t.Status='IN_TRANSIT' AND l.ProductId="+inventoryId+" AND l.Quantity=4",connection).ExecuteScalarAsync())==1,"Transfer document records destination and quantity");
  Check(Convert.ToInt32(await new SqlCommand("SELECT COUNT(*) FROM StockLedger WHERE ProductId="+inventoryId+" AND MovementType='STOCK_TRANSFER_OUT' AND Quantity<0",connection).ExecuteScalarAsync())>=1,"Transfer ledger movement exists");
  var dateWise=await http.GetAsync("/api/inventory/stock-date-wise?from=2020-01-01&to=2035-12-31&q=Inventory");Check(dateWise.IsSuccessStatusCode,"Date-wise stock endpoint reads ledger movements");
  Console.WriteLine("PASS: Inventory damage, receive, transfer and date-wise stock SQL transactions");
  foreach(var type in new[]{"account-report","cashier-report","payment-mode-report","expense-report","day-close-report","audit-trail-report"})
